<script setup lang="ts">
import { Link } from '@inertiajs/vue3';
import { ref } from 'vue';
type Order={id:number;status:string;created_at:string;price_cents:number;game:{name:string;platform:string}};
const props=defineProps<{orders:{data:Order[];next_page_url:string|null;prev_page_url:string|null}}>();
const revealed=ref<Record<number,string>>({});const errors=ref<Record<number,string>>({});const busy=ref<Record<number,boolean>>({});
async function reveal(id:number){busy.value[id]=true;errors.value[id]='';try{const res=await fetch(`/my-orders/${id}/reveal`,{credentials:'same-origin',headers:{'Accept':'application/json'}});if(!res.ok)throw new Error('Unable to reveal key');const body=await res.json();revealed.value[id]=body.code;}catch(e){errors.value[id]='Unable to reveal the key. Refresh and try again.';}finally{busy.value[id]=false;}}
</script>
<template><main class="min-h-screen bg-[#090b18] px-6 py-8 text-white"><div class="mx-auto max-w-5xl"><header class="flex items-center justify-between"><Link href="/games" class="text-2xl font-black">GAME<span class="text-violet-400">VAULT</span></Link><Link href="/games" class="text-sm text-violet-300">← Browse games</Link></header><h1 class="mb-3 mt-16 text-5xl font-black">Your collection.</h1><p class="mb-10 text-slate-400">Every adventure you've unlocked, in one place.</p><div class="space-y-4"><article v-for="order in orders.data" :key="order.id" class="flex flex-wrap items-center gap-5 rounded-2xl border border-white/10 bg-[#141728] p-6"><div class="flex h-16 w-16 items-center justify-center rounded-xl bg-violet-700/40 font-bold">GV</div><div class="min-w-48 flex-1"><h2 class="font-bold">{{order.game.name}}</h2><p class="mt-1 text-xs text-slate-400">Order #{{order.id}} · {{order.game.platform}}</p></div><div class="text-right"><span class="rounded-lg px-3 py-1 text-xs font-semibold" :class="order.status==='delivered'?'bg-emerald-500/20 text-emerald-300':order.status==='failed'?'bg-rose-500/20 text-rose-300':'bg-amber-500/20 text-amber-300'">{{order.status}}</span><p class="mt-3 font-mono text-sm">{{revealed[order.id]||'XXXXX-XXXXX-XXXXX'}}</p><button v-if="order.status==='delivered'" @click="revealed[order.id]?delete revealed[order.id]:reveal(order.id)" class="mt-2 text-xs text-violet-300 underline" :disabled="busy[order.id]">{{busy[order.id]?'Loading...':revealed[order.id]?'Hide key':'Reveal key'}}</button><p v-if="errors[order.id]" class="mt-2 text-xs text-rose-300" role="alert">{{errors[order.id]}}</p></div></article></div><p v-if="!orders.data.length" class="mt-12 rounded-xl border border-white/10 p-10 text-center text-slate-400">No orders yet. Your next adventure awaits.</p><div class="mt-8 flex gap-4"><Link v-if="orders.prev_page_url" :href="orders.prev_page_url" class="text-violet-300">← Previous</Link><Link v-if="orders.next_page_url" :href="orders.next_page_url" class="text-violet-300">Next →</Link></div></div></main></template>
